/// <summary>
/// CB714_POConfirmationReports
/// Extension of class <c>SalesConfirmDP</c>
/// </summary>
[ExtensionOf(classStr(PurchPurchaseOrderDP))]
final class METPurchPurchaseOrderDP_Extension
{


}

Method.Source:
    /// <summary>
    /// Insert the order header.
    /// </summary>
    /// <param name = "_purchaseOrderHeader">
    /// A <c>PurchPurchaseOrderHeader</c> record to insert.
    /// </param>
    protected void insertOrderHeader(PurchPurchaseOrderHeader _purchaseOrderHeader)
    {
        #ISOCountryRegionCodes
        #PrintMgmtSetup

        DirPartyTable               dirPartyTable;
        LogisticsLocation           logisticsLocation;
        HcmWorker                   hcmWorker;
        SysDocuBrandDetails         docuBrandDetails;
        LogisticsPostalAddress      address;
        DirPartyLocation            dirPartyLocation;
        PurchTable                  purchTable      = PurchTable::find(_purchaseOrderHeader.PurchId);
        InventLocation              inventLocation  = InventLocation::find(purchTable.InventLocationId);
        METPurchTable               metPurchTable   = METPurchTable::findByPurchTable(purchTable.RecID);
        METIndustryKeyTable         industryKey     = METIndustryKeyTable::find(inventLocation.METWHSubEntity);
        CompanyInfo                 companyInfo     = CompanyInfo::find();
        VendTable                   vendTable       = VendTable::find(purchTable.OrderAccount);
        SRSReportName               reportName      = docuBrandContract.parmReportName();
        SRSReportDesignName         reportDesignName = docuBrandContract.parmDesignName();
        
        select firstonly Image1Name, METTaxRegNumber, METReportNotes, NotesLine1, NotesLine2 from docuBrandDetails
            where docuBrandDetails.ReportName ==  reportName
            && docuBrandDetails.DesignName == reportDesignName
            && docuBrandDetails.METIndustryKey == inventLocation.METWHSubEntity;

        _purchaseOrderHeader.METVendVATNum          = VendTable.VATNum;
        _purchaseOrderHeader.METPurchOrderAccount   = purchTable.OrderAccount;
        _purchaseOrderHeader.CompanyLogo            = SysDocuBrandImages::getImage(docuBrandDetails.Image1Name);
        _purchaseOrderHeader.CompanyName            = industryKey.CompanyName;
        PurchaseOrderId docNum                      = _purchaseOrderHeader.PurchOrderDocNum;
                
        //Import PO report 
        if (VendTable.VendGroup == METConstants::ImportPOVendorGroup && purchTable.PurchPoolId == METConstants::ImportPOPoolId)
        {
            _purchaseOrderHeader.CompanyCoRegNum            = docuBrandDetails.METTaxRegNumber;
            _purchaseOrderHeader.FormLetterRemarksTxt       = docuBrandDetails.METReportNotes + METConstants::NextLine + docuBrandDetails.NotesLine1 + METConstants::NextLine + docuBrandDetails.NotesLine2;
            LogisticsLocationRoleRecId roleHeadCompanyRecId = LogisticsLocationRole::findByName(METConstants::HeadCompanyRole).RecId;
            
            select firstonly PrimaryAddressLocation, RecId from dirPartyTable 
                where dirPartyTable.RecId == companyInfo.RecId;

            if (dirPartyTable.RecId)
            {
                dirPartyLocation = DirPartyLocation::findByPartyLocation(dirPartyTable.RecId, dirPartyTable.PrimaryAddressLocation);

                _purchaseOrderHeader.METEntityAddress   = this.getCompanyAddress(dirPartyLocation.RecId, roleHeadCompanyRecId);
                _purchaseOrderHeader.METContactPhone    = this.getCompanyElectronicAddressByTypeAndPurpose(dirPartyLocation.RecId, dirPartyLocation.Location, roleHeadCompanyRecId, LogisticsElectronicAddressMethodType::Phone);
                _purchaseOrderHeader.METContactEmail    = this.getCompanyElectronicAddressByTypeAndPurpose(dirPartyLocation.RecId, dirPartyLocation.Location,roleHeadCompanyRecId, LogisticsElectronicAddressMethodType::Email);
            }

            LogisticsLocationRoleRecId invoiceRoleRecId = LogisticsLocationRole::findByName(METConstants::InvoiceRole).RecId;

            _purchaseOrderHeader.METOrderToDetails = this.getVendorAddressByInvoice(vendTable.party, DirPartyTable::findRec(vendTable.party).PrimaryAddressLocation, invoiceRoleRecId);
            
            _purchaseOrderHeader.METPurchConfirmDate                = vendPurchOrderJour.PurchOrderDate;
            _purchaseOrderHeader.METReceivingDockDetails            = purchTable.ITMFromPort;
            _purchaseOrderHeader.METDestinationPortDetails          = metPurchTable.POIMPDestinationPort;
            _purchaseOrderHeader.METPOIMPGoodsReadyNoLtrThanDate    = metPurchTable.POIMPGoodsReadyNoLtrThanDate;
            _purchaseOrderHeader.METPOIMPLastShipDate               = metPurchTable.POIMPLastShipDate;

            VendTable freightVendor = VendTable::find(VendTable.ITMAgent);

            if (freightVendor)
            {
                _purchaseOrderHeader.METFreightForwarderName = freightVendor.name();

                _purchaseOrderHeader.METFreightForwarderAddress = DirParty::primaryPostalAddress(freightVendor.Party, DateTimeUtil::getSystemDateTime()).Address;

                RefRecId primaryaddressLocation = DirPartyTable::findRec(freightVendor.Party).PrimaryAddressLocation;

                if (primaryaddressLocation)
                {
                    LogisticsLocationRecId logisticsLocationRecId = this.getPrimaryPostalAddressBasedOnParty(primaryaddressLocation);
                    LogisticsLocationRecId locationByDirParty = this.getLocationBasedOnDirPartyLocation(freightVendor.Party, logisticsLocationRecId);

                    logisticsLocation.clear();

                    select firstonly RecId from logisticsLocation
                        where logisticsLocation.ParentLocation == locationByDirParty;

                    _purchaseOrderHeader.METFreightContactName = LogisticsElectronicAddress::findByLocationAndType(logisticsLocation.RecId, LogisticsElectronicAddressMethodType::Phone).Description ;
                    _purchaseOrderHeader.METForwarderEmail = this.getEmailOrPhoneBasedOnReferenceRecId(logisticsLocation.RecId, LogisticsElectronicAddressMethodType::Email, NoYes::Yes);
                    _purchaseOrderHeader.METForwarderPhoneNumber =  this.getEmailOrPhoneBasedOnReferenceRecId(logisticsLocation.RecId, LogisticsElectronicAddressMethodType::Phone, NoYes::Yes);
                }
            }
            _purchaseOrderHeader.DlvTerm = purchTable.DlvTerm;
            _purchaseOrderHeader.METDeliveryDate = purchTable.DeliveryDate;
        }
        else
        {
            _purchaseOrderHeader.FormLetterRemarksTxt = docuBrandDetails.METReportNotes + METConstants::NextLine + docuBrandDetails.NotesLine1 + METConstants::NextLine + docuBrandDetails.NotesLine2;
  
            _purchaseOrderHeader.CompanyCoRegNum = industryKey.CoRegNum;
            
            if (metPurchTable.POSubSource)
            {
                _purchaseOrderHeader.METOrderToDetails = strFmt("@MET:TradePOSuppilerNumberWithSub",
                                                                 purchTable.OrderAccount,
                                                                 metPurchTable.POSubSource);
            }
            else
            {
                _purchaseOrderHeader.METOrderToDetails = strFmt("@MET:TradePOSuppilerNumberWithoutSub",
                                                                purchTable.OrderAccount);
            }

            if (companyInfo.METLegalEntityType == METLegalEntityType::Liquor && metPurchTable.UnderBond)
            {
                _purchaseOrderHeader.METHeaderUnderBondStatus = "@MET:METUnderBondPO";
            }

            _purchaseOrderHeader.METDeliveryDate = purchTable.DeliveryDate;
            _purchaseOrderHeader.METShipDate = purchTable.ITMDate;

            _purchaseOrderHeader.METReceivingDockDetails = this.getWareHouseAddressByRecevingDock(inventLocation.RecId, 
                                                                                                   LogisticsLocationRole::findByName(METConstants::ReceivingDock).RecId, 
                                                                                                   LogisticsElectronicAddressMethodType::Phone);
            
            

            if (inventLocation.METWHSubEntity == METConstants::SubEntityWareHouseCCC)
            {
                _purchaseOrderHeader.METCCCSubEntity = NoYes::Yes;
            }
            else
            {
                _purchaseOrderHeader.METCCCSubEntity = NoYes::No;
            } 
        }

        if (purchTable.ReqAttention)
        {
            _purchaseOrderHeader.METSpecialInstructions = substr(purchTable.ReqAttention, 1, 50);
        }

        _purchaseOrderHeader.METVendorRef = purchTable.VendorRef;
        _purchaseOrderHeader.PurchOrderDate = purchTable.createDate();
        _purchaseOrderHeader.METVersionText = strFmt("@MET:METVersion", substr(docNum, strFind(docNum, METConstants::hyphen, 1, 999) + 1, 999));
                
        if (purchTable.ItemBuyerGroupId)
        {
            hcmWorker = HcmWorker::find(InventBuyerGroup::find(purchTable.ItemBuyerGroupId).METOrderer);

            _purchaseOrderHeader.METPlannerContactName = hcmWorker.name();
            
            dirPartyTable.clear();
            select firstonly PrimaryContactEmail, PrimaryContactPhone from dirPartyTable where dirPartyTable.RecId == hcmWorker.Person;

            _purchaseOrderHeader.METPlannerContactEmail = LogisticsElectronicAddress::findRecId(dirPartyTable.PrimaryContactEmail).Locator;

            if (inventLocation.METWHSubEntity == METConstants::SubEntityWareHouseCCC)
            {  
                _purchaseOrderHeader.METPlannerContactPhone = this.getWareHouseAddressByRecevingDock(inventLocation.RecId,LogisticsLocationRole::findByName(METConstants::Reception).RecId, LogisticsElectronicAddressMethodType::Phone);
            }
            else
            {
                _purchaseOrderHeader.METPlannerContactPhone = LogisticsElectronicAddress::findRecId(dirPartyTable.PrimaryContactPhone).Locator;
            }     
        }

        if (purchTable.PurchStatus == PurchStatus::Canceled)
        {
            _purchaseOrderHeader.METHeaderStatus = "@MET:METCancelledPO";
        }

        _purchaseOrderHeader.METLegendText = VendFormletterParameters::find().METPurchOrderReportLegendText;

        Email deliverToEmail = this.getContactEmailFromPurchId(purchTable.PurchId);
        
        _purchaseOrderHeader.METDeliveryAddressWithAdditionalDetails = _purchaseOrderHeader.DeliveryAddress;

        if (deliverToEmail)
        {
            _purchaseOrderHeader.METDeliveryAddressDetail2 += strFmt("@MET:METContact", deliverToEmail);
        }

        address = LogisticsLocationEntity::findPostalAddress(companyInfo, LogisticsLocationRoleType::HeadCompany_IT);

        if (address)
        {
            _purchaseOrderHeader.CompanyAddress = address.Address;
        }

        LogisticsPostalAddress whAddress = LogisticsLocationEntity::findPostalAddress(inventLocation, LogisticsLocationRoleType::Delivery, DateTimeUtil::utcNow(), true);

        _purchaseOrderHeader.METWarehouseName = inventLocation.Name;

        if (whAddress.RecId)
        {
            _purchaseOrderHeader.METWarehouseAddress = whAddress.Address;
            _purchaseOrderHeader.METWarehousePhone = this.getPhoneNumberFromContact(whAddress.Location);
        }

        _purchaseOrderHeader.METSubSource = metPurchTable.POSubSource;

        next insertOrderHeader(_purchaseOrderHeader);
    }

    /// <summary>
    /// Initializes the purchase order header.
    /// </summary>
    /// <param name = "_vendPurchOrderJour">
    /// A <c>VendPurchOrderJour</c> purchase order journal header which the order header is initialized from.
    /// </param>
    /// <returns>
    /// The initialized <c>PurchPurchaseOrderHeader</c> record.
    /// </returns>
    protected PurchPurchaseOrderHeader initializePurchaseOrderHeader(VendPurchOrderJour _vendPurchOrderJour)
    {
        PurchPurchaseOrderHeader    metPurchPurchaseOrderHeader;

        metPurchPurchaseOrderHeader = next initializePurchaseOrderHeader(_vendPurchOrderJour);

        metPurchPurchaseOrderHeader.SalesOrderBalance          = _vendPurchOrderJour.SalesOrderbalance;
        metPurchPurchaseOrderHeader.EndDisc                    = _vendPurchOrderJour.EndDisc;
        metPurchPurchaseOrderHeader.SumMarkup                  = _vendPurchOrderJour.SumMarkup;
        metPurchPurchaseOrderHeader.SumTax                     = _vendPurchOrderJour.SumTax;
        metPurchPurchaseOrderHeader.RoundOff                   = _vendPurchOrderJour.RoundOff;
        metPurchPurchaseOrderHeader.Amount                     = _vendPurchOrderJour.Amount;

        return metPurchPurchaseOrderHeader;
    }

    /// <summary>
    /// Insert the order line.
    /// </summary>
    /// <param name = "_purchaseOrderTmp">order line record to insert</param>
    protected void insertOrderLine(PurchPurchaseOrderTmp _purchaseOrderTmp)
    {
        PurchLine           purchLine           = PurchLine::findInventTransId(_purchaseOrderTmp.PurchLineInventTransId);
        InventDim           inventDim           = purchLine.inventDim();
        InventTable         inventTable         = InventTable::find(purchLine.ItemId);
        METLegalEntityType  metLegalEntity      = CompanyInfo::find().METLegalEntityType;
        VendTable           vendTable           = purchLine.vendTable_OrderAccount();
        PurchTable          purchTable          = purchLine.purchTable();

        _purchaseOrderTmp.METPurchStatus        = purchLine.PurchStatus;
        _purchaseOrderTmp.METGTIN               = purchLine.BarCode;
        _purchaseOrderTmp.Qty                   = purchLine.PurchQty;
        _purchaseOrderTmp.METUOMPurchaseTxt     = InventTable::find(purchLine.ItemId).inventItemPurchSetup(purchLine.inventdimid).METPurchUnit;
        
        _purchaseOrderTmp.PurchUnitTxt          = purchLine.PurchUnit;
        _purchaseOrderTmp.METName               = inventTable.productName(SystemParameters::getSystemLanguageId());
        _purchaseOrderTmp.IsUpdated             = METPurchLine::find(purchLine.recId).POAChangeIndicator;
        _purchaseOrderTmp.TaxAmount             = purchLine.PurchPrice;
        
        if (purchLine.PurchUnit == METConstants::unitEach)
        {
            _purchaseOrderTmp.METPurchPrice = purchLine.PurchPrice;
        }
        else
        {
            PurchUnit invPurchUnit = InventTableModule::find(purchLine.ItemId, ModuleInventPurchSales::Invent).UnitId;
            PurchPrice convertedPurchPrice = UnitOfMeasureConversion::findByConversion(UnitOfMeasure::findBySymbol(purchLine.PurchUnit).RecId,
                                                      UnitOfMeasure::findBySymbol(invPurchUnit).RecId,
                                                      EcoResProduct::findByProductNumber(purchLine.ItemId).RecId).Factor;

            if (convertedPurchPrice)
            {
                _purchaseOrderTmp.METPurchPrice = purchLine.PurchPrice/convertedPurchPrice;
            }
            else
            {
                _purchaseOrderTmp.METPurchPrice = purchLine.PurchPrice;
            }
        }
        _purchaseOrderTmp.PurchPrice = purchLine.PurchPrice;

        //Trade PO
        if (VendTable.VendGroup != METConstants::ImportPOVendorGroup || purchTable.PurchPoolId != METConstants::ImportPOPoolId)
        {
            if (purchLine.PurchStatus == PurchStatus::Canceled)
            {
                _purchaseOrderTmp.Qty = 0;
            }
            
            _purchaseOrderTmp.TaxAmount = purchLine.ConfirmedTaxAmount;
            _purchaseOrderTmp.METAmountIncTax = _purchaseOrderTmp.TaxAmount +  _purchaseOrderTmp.LineAmount;

            METInventItemOrderSetup metInventItemOrderSetup;

            select firstonly TempRcvLimit, CartonPerLayer, Layers
                from metInventItemOrderSetup
                where metInventItemOrderSetup.ItemId == purchLine.ItemId
                && metInventItemOrderSetup.SiteId == inventDim.InventSiteId;

            METTempRcvLimit tempRcvLimit = metInventItemOrderSetup.TempRcvLimit;
           
            _purchaseOrderTmp.METTi = metInventItemOrderSetup.CartonPerLayer;
            _purchaseOrderTmp.METHi = metInventItemOrderSetup.Layers;
            _purchaseOrderTmp.METMLOR = tempRcvLimit ? tempRcvLimit : inventTable.PdsBestBefore;

            if (_purchaseOrderTmp.METTi || _purchaseOrderTmp.METHi)
            {
                Qty metPalleyQty;

                if (_purchaseOrderTmp.METTi > 0)
                {
                    metPalleyQty = _purchaseOrderTmp.Qty / _purchaseOrderTmp.METTi;

                    if (_purchaseOrderTmp.METHi > 0)
                    {
                        metPalleyQty = metPalleyQty/_purchaseOrderTmp.METHi;
                    }

                    _purchaseOrderTmp.METPalletQty = System.Math::Ceiling(metPalleyQty);
                }

                else if (_purchaseOrderTmp.METTi == 0 && _purchaseOrderTmp.METHi > 0)
                {
                    metPalleyQty = _purchaseOrderTmp.Qty/_purchaseOrderTmp.METHi;

                    _purchaseOrderTmp.METPalletQty = System.Math::Ceiling(metPalleyQty);
                    
                }
                else
                {
                    // If both are zero or negative, set METPalletQty to zero
                    _purchaseOrderTmp.METPalletQty = 0;
                }
            }

            if (_purchaseOrderTmp.METPalletQty == 0)
            {
                _purchaseOrderTmp.METPalletQty = 1;
            }

            if (metLegalEntity == METLegalEntityType::Food)
            {
                _purchaseOrderTmp.METMinDays = tempRcvLimit;
                _purchaseOrderTmp.METFoodEntity = NoYes::Yes;
            }
        }

        _purchaseOrderTmp.CurrencyCode = VendTable::find(purchLine.orderAccount()).Currency;
        
        HMIMItemMaterial hmimItemMaterial;
        
        select firstonly RecId, ClassCode, DivisionCode, RegCode from hmimItemMaterial
            where hmimItemMaterial.ItemId == purchLine.ItemId;

        _purchaseOrderTmp.METDangerousGoods = hmimItemMaterial.RegCode != '' ? METConstants::Y : METConstants::N;

        if (hmimItemMaterial.RecId)
        {
            _purchaseOrderTmp.METClassCode = hmimItemMaterial.ClassCode;
            _purchaseOrderTmp.METDivisionCode = hmimItemMaterial.DivisionCode;
        }

        WHSPhysDimUOM physDim = WHSPhysDimUOM::findByItemIdAndUnitOfMeasure(purchLine.ItemId, _purchaseOrderTmp.PurchUnitTxt);
        _purchaseOrderTmp.METNetWeight = physDim.METNetWeight;
        _purchaseOrderTmp.METPurchOrderFormNum = purchTable.PurchOrderFormNum;

        if (_purchaseOrderTmp.Qty < 0)
        {
            _purchaseOrderTmp.METAmountIncTax = purchLine.ConfirmedTaxAmount + _purchaseOrderTmp.LineAmount;
        }

        next insertOrderLine(_purchaseOrderTmp);
    }

    /// <summary>
    /// get the Email address
    /// </summary>
    /// <param name = "_metPurchId">PurchId</param>
    /// <returns>Email</returns>
    public METWHEmail getContactEmailFromPurchId(PurchId _metPurchId)
    {
        LogisticsEntityPostalAddressView    metPostalAddressViewStd;
        LogisticsElectronicAddress          metElectronicAddressStd;
        LogisticsLocation                   metContactLocationStd;
        PurchTable                          metPurchTableStd;
        InventLocation                      metInventLocationStd;

        select firstonly Locator from metElectronicAddressStd
            exists join metPostalAddressViewStd
            exists join metPurchTableStd
            exists join metInventLocationStd
                where metPurchTableStd.InventLocationId == metInventLocationStd.InventLocationId
                && metPurchTableStd.PurchId == _metPurchId
                && metPostalAddressViewStd.Entity == metInventLocationStd.RecId
                && metElectronicAddressStd.Type == LogisticsElectronicAddressMethodType::Email
            exists join metContactLocationStd
                where metContactLocationStd.ParentLocation == metPostalAddressViewStd.Location
                && metContactLocationStd.RecId == metElectronicAddressStd.Location;

        return metElectronicAddressStd.Locator;

    }

    /// <summary>
    /// Get METcash logo based on entity
    /// </summary>
    /// <param name = "_legalEntityType">LegalEntityType</param>
    /// <param name = "_subEntityWareHouse">SubEntity warehouse</param>
    /// <returns>Image</returns>
    public container getCompanyLogo(METLegalEntityType _legalEntityType, InventLocationId _subEntityWareHouse)
    {
        container image;

        switch(_legalEntityType)
        {
            case METLegalEntityType::Food:
                image = SysDocuBrandImages::getImage(_subEntityWareHouse);
                break;

            case METLegalEntityType::Liquor:
                image = SysDocuBrandImages::getImage(METConstants::LiquorLogo);
                break;

            default:
                break;

        }
        return image;
    }

    /// <summary>
    /// Get METcash logo based on entity
    /// </summary>
    /// <param name = "_industryKey">Industry Key</param>
    /// <returns>SysDocuBrandDetails</returns>
    public SysDocuBrandDetails getDocuBrandDeliveryDetails(METIndustryKey _industryKey)
    {
        SysDocuBrandDetails docuBrandDetails;

        str brandId = _industryKey + METConstants::DeliveryNotes;

        select docuBrandDetails
                where docuBrandDetails.BrandId == brandId;

        return docuBrandDetails;
        
    }

    /// <summary>
    /// get the phone number for receiving dock
    /// </summary>
    /// <param name = "_metLogisticsLocationRole">LogisticsLocationRole</param>
    /// <param name = "_metPurchId">met purch id</param>
    /// <returns>Phone</returns>
    public METWHPhone getPurchOrderDeliveryAddressContactPhoneByRole(LogisticsLocationRole _metLogisticsLocationRole, PurchId _metPurchId)
    {
        LogisticsEntityPostalAddressView    metPostalAddressViewStd;
        LogisticsElectronicAddress          metElectronicAddressStd;
        LogisticsLocation                   metContactLocationStd;
        PurchTable                          metPurchTableStd;
        InventLocation                      metInventLocationStd;
        LogisticsElectronicAddressRole      metElectronicAddressRole;

        select firstonly Locator from metElectronicAddressStd
            exists join metElectronicAddressRole
                where metElectronicAddressRole.LocationRole == _metLogisticsLocationRole.RecId
                    && metElectronicAddressRole.ElectronicAddress == metElectronicAddressStd.RecId
            exists join metPostalAddressViewStd
                exists join metPurchTableStd
            exists join metInventLocationStd
            where metPurchTableStd.InventLocationId == metInventLocationStd.InventLocationId
                && metPurchTableStd.PurchId          == _metPurchId
                && metPurchTableStd.DeliveryPostalAddress == metPostalAddressViewStd.PostalAddress
                && metPostalAddressViewStd.Entity     == metInventLocationStd.RecId
                && metElectronicAddressStd.Type == LogisticsElectronicAddressMethodType::Phone
            exists join metContactLocationStd
            where metContactLocationStd.ParentLocation  == metPostalAddressViewStd.Location
                  && metContactLocationStd.RecId == metElectronicAddressStd.Location;

        return metElectronicAddressStd.Locator;

    }

    /// <summary>
    /// Get Company ElectronicAddress By Type And Purpose
    /// </summary>
    /// <param name = "_dirPartyLocationRecId">DirPartyLocation recId</param>
    /// <param name = "_dirpartyLocationlocationRecId">DirpartyLocation location</param>
    /// <param name = "_roleHeadCompanyRecId">HeadCompanyRole</param>
    /// <param name = "_type">LogisticsElectronicAddressMethodType</param>
    /// <returns>ElectronicAddress</returns>
    public LogisticsElectronicAddressLocator getCompanyElectronicAddressByTypeAndPurpose(RefRecId _dirPartyLocationRecId,
                                                                                         LogisticsLocationRoleRecId _dirpartyLocationlocationRecId,
                                                                                         LogisticsLocationRoleRecId _roleHeadCompanyRecId,
                                                                                         LogisticsElectronicAddressMethodType _type)
    {
        LogisticsLocation  logisticsLocation;
        LogisticsElectronicAddress logisticsElectronicAddress;
        DirPartyLocationRole dirPartyLocationRole;

        select firstonly RecId from logisticsLocation
            where logisticsLocation.ParentLocation == _dirpartyLocationlocationRecId
        join Locator from logisticsElectronicAddress
            where logisticsElectronicAddress.Location == logisticsLocation.RecId
            && logisticsElectronicAddress.type == _type
        exists join dirPartyLocationRole
            where dirPartyLocationRole.PartyLocation == _dirPartyLocationRecId
            && dirPartyLocationRole.LocationRole == _roleHeadCompanyRecId;
        

        return logisticsElectronicAddress.Locator;
    }

    /// <summary>
    /// Get METcash logo based on entity
    /// </summary>
    /// <param name = "_industryKey">Industry Key</param>
    /// <returns>SysDocuBrandDetails</returns>
    public SysDocuBrandDetails getDocuBrandDetails(METIndustryKey _industryKey)
    {
        SysDocuBrandDetails docuBrandDetails;
        
        str brandId = strFmt("@MET:BrandId", _industryKey);

        select firstonly docuBrandDetails
            where docuBrandDetails.BrandId == brandId;

        return docuBrandDetails;
    }

    /// <summary>
    /// Get company Address
    /// </summary>
    /// <param name = "_dirPartyLocationRecId">DirPartyLocation Recid</param>
    /// <param name = "_headCompanyRole">Head Company role</param>
    /// <returns>LogsiticsAdress</returns>
    public LogisticsAddressing getCompanyAddress(RefRecId _dirPartyLocationRecId, LogisticsLocationRoleRecId _headCompanyRole)
    {
        DirPartyPostalAddressView dirPartyPostalAddressView;
        DirPartyLocationRole dirPartyLocationRole;

        select firstonly Address from dirPartyPostalAddressView
            where dirPartyPostalAddressView.RecId == _dirPartyLocationRecId
            && dirPartyPostalAddressView.ValidFrom <=  DateTimeUtil::getSystemDateTime()
            && dirPartyPostalAddressView.ValidTo >= DateTimeUtil::getSystemDateTime()
        exists join dirPartyLocationRole
            where dirPartyLocationRole.PartyLocation == _dirPartyLocationRecId
            && dirPartyLocationRole.LocationRole == _headCompanyRole;
    
        return dirPartyPostalAddressView.Address; 
    }

    /// <summary>
    /// Get DirPartyPostalAddressView based on Dirparty recId and Location reference
    /// </summary>
    /// <param name = "_partyRecId">Dirparty recId </param>
    /// <param name = "_locationRecId">Location reference Id</param>
    /// <returns>DirPartyPostalAddressView buffer</returns>
    private DirPartyPostalAddressView getDirPartyPostalAddressView(DirPartyRecId _partyRecId, LogisticsLocationRecId _locationRecId)
    {
        DirPartyPostalAddressView dirPartyPostalAddressView;

        select dirPartyPostalAddressView
            where dirPartyPostalAddressView.Party == _partyRecId
            && dirPartyPostalAddressView.Location == _locationRecId
            && dirPartyPostalAddressView.ValidFrom <=  DateTimeUtil::getSystemDateTime()
            && dirPartyPostalAddressView.ValidTo >= DateTimeUtil::getSystemDateTime();

        return dirPartyPostalAddressView;
    }

    /// <summary>
    /// Get Email Or Phone Based On Reference RecId
    /// </summary>
    /// <param name = "_locationRecId">location reference</param>
    /// <param name = "_type">LogisticsElectronicAddressMethodType</param>
    /// <param name = "_isPrimary">Check if primary or not</param>
    /// <returns>LogisticsElectronicAddressLocator</returns>
    public LogisticsElectronicAddressLocator getEmailOrPhoneBasedOnReferenceRecId(RefRecId _locationRecId, LogisticsElectronicAddressMethodType _type, NoYesId _isPrimary = NoYes::No)
    {
        LogisticsElectronicAddress logisticsElectronicAddress;

        select firstonly Locator from logisticsElectronicAddress
            where logisticsElectronicAddress.Location == _locationRecId
            && logisticsElectronicAddress.IsPrimary == _isPrimary
            && logisticsElectronicAddress.type == _type;
       
        return logisticsElectronicAddress.Locator;
    }

    /// <summary>
    /// Get Vendor address by Invoice Purpose
    /// </summary>
    /// <param name = "_party">DirPartyRecid</param>
    /// <param name = "_locationRecId">LocationRecId</param>
    /// <param name = "_invoiceRoleRecId">InvoiceRoleRecId</param>
    /// <returns>Address</returns>
    public LogisticsAddressing getVendorAddressByInvoice(RefRecId _party, LogisticsLocationRecId _locationRecId, LogisticsLocationRoleRecId _invoiceRoleRecId)
    {
        DirPartyPostalAddressView   dirPartyPostalAddressView;
        DirPartyLocationRole        dirPartyLocationRole;

        select firstonly RecId, Address from dirPartyPostalAddressView
            where dirPartyPostalAddressView.Party == _party
            && dirPartyPostalAddressView.Location == _locationRecId
            && dirPartyPostalAddressView.ValidFrom <= DateTimeUtil::getSystemDateTime()
            && dirPartyPostalAddressView.ValidTo >= DateTimeUtil::getSystemDateTime()
        exists join dirPartyLocationRole
            where dirPartyLocationRole.PartyLocation == dirPartyPostalAddressView.RecId
            && dirPartyLocationRole.LocationRole == _invoiceRoleRecId;

        return dirPartyPostalAddressView.Address;
        
    }

    /// <summary>
    /// Get PrimaryPostalAddress based on party
    /// </summary>
    /// <param name = "_primaryAddressLocation">Primary postal address</param>
    /// <returns>LogisticsLocationRecId</returns>
    private LogisticsLocationRecId getPrimaryPostalAddressBasedOnParty(RefRecId _primaryAddressLocation)
    {
        LogisticsPostalAddress      logsiticsPostalAddress;

        select firstonly Location from logsiticsPostalAddress
            where logsiticsPostalAddress.Location == _primaryAddressLocation
            && logsiticsPostalAddress.ValidFrom <= DateTimeUtil::getSystemDateTime()
            && logsiticsPostalAddress.ValidTo >= DateTimeUtil::getSystemDateTime();

        return logsiticsPostalAddress.Location;

    }

    /// <summary>
    /// Get Location based on DirPartytLocation
    /// </summary>
    /// <param name = "_party">Party RecId</param>
    /// <param name = "_location">DirpArty PostalAddress location</param>
    /// <returns>Location details from DirpartyLocation</returns>
    private LogisticsLocationRecId getLocationBasedOnDirPartyLocation(RefRecId _party, RefRecId _location)
    {
        DirPartyLocation            dirPartyLocation;

        select firstonly Location from dirPartyLocation
            order by dirPartyLocation.AssignmentDate desc
            where dirPartyLocation.Party == _party
            && dirPartyLocation.Location == _location;
           
        return dirPartyLocation.Location;
    }

    /// <summary>
    /// Get Logsitic Location By ParentLocation
    /// </summary>
    /// <param name = "_locationRecId">Reference RecId</param>
    /// <returns>Logistics Location RecId</returns>
    private RecId getLogsiticLocationByParentLocation(LogisticsLocationRecId _locationRecId)
    {
        LogisticsLocation           logisticsLocation;

        select firstonly RecId from logisticsLocation
                where logisticsLocation.ParentLocation == _locationRecId;

        return logisticsLocation.RecId;
    }

    /// <summary>
    /// Get WareHouse address By recevingdock role
    /// </summary>
    /// <param name = "_inventLocationRecId">Location RecId</param>
    /// <param name = "_roleRecId">Role Recid</param>
    /// <param name = "_type">LogisticsElectronicAddressMethodType</param>
    /// <returns>Locator</returns>
    private LogisticsElectronicAddressLocator getWareHouseAddressByRecevingDock(RefRecId _inventLocationRecId, LogisticsLocationRoleRecId _roleRecId, LogisticsElectronicAddressMethodType _type)
    {
        LogisticsEntityPostalAddressView  logisticsEntityPostalAddressView;
        InventLocationLogisticsLocationRole inventLocationLogisticsLocationRole;
        LogisticsElectronicAddressLocator locator;
        LogisticsLocation   logisticsLocation;
        LogisticsElectronicAddress  logisticsElectronicAddress;

        
        select firstonly logisticsEntityPostalAddressView
            where logisticsEntityPostalAddressView.Entity == _inventLocationRecId
            && logisticsEntityPostalAddressView.EntityType == LogisticsLocationEntityType::Warehouse
            && logisticsEntityPostalAddressView.ValidFrom <= DateTimeUtil::getSystemDateTime()
            && logisticsEntityPostalAddressView.ValidTo >= DateTimeUtil::getSystemDateTime()
        join firstonly inventLocationLogisticsLocationRole
            where inventLocationLogisticsLocationRole.LocationLogisticsLocation == logisticsEntityPostalAddressView.EntityLocation
            && inventLocationLogisticsLocationRole.LocationRole == _roleRecId
        join firstonly logisticsLocation
            where logisticsLocation.ParentLocation == logisticsEntityPostalAddressView.Location
        join firstonly logisticsElectronicAddress
            where logisticsElectronicAddress.Location == logisticsLocation.RecId
            && logisticsElectronicAddress.type == _type;

        if (inventLocationLogisticsLocationRole && logisticsElectronicAddress)
        {
            locator = logisticsElectronicAddress.locator;
        }

        return locator;
   
    }

    /// <summary>
    /// Gets the phone details from the contact information.
    /// </summary>
    /// <param name = "_locationRecId">_locationRecId</param>
    /// <returns>LogisticsElectronicAddressLocator</returns>
    private LogisticsElectronicAddressLocator getPhoneNumberFromContact(RefRecId _locationRecId)
    {
        LogisticsElectronicAddress electronicAddress;
        LogisticsLocation contactLocation;

        select firstOnly Locator from electronicAddress 
            where electronicAddress.Type == LogisticsElectronicAddressMethodType::Phone
        exists join contactLocation 
            where contactLocation.ParentLocation  == _locationRecId
                && contactLocation.RecId == electronicAddress.Location;

        return electronicAddress.Locator;
    }
